import React, { useCallback, useEffect, useState, useRef } from 'react';
import { Card, Tag, Pagination, Input, DatePicker, Button, Select, Space, Divider, message } from 'antd';
import { useNavigate, useLocation } from 'react-router-dom';
import { SearchOutlined, EnvironmentOutlined, UserOutlined, FileTextOutlined } from '@ant-design/icons';
import { orderAPI, waitlistAPI } from '../../services/api';
import { useAuth } from '../../hooks/useAuth';
import "./style.css";

const { Search } = Input;
const { Option } = Select;

// 订单状态映射
const ORDER_STATUS = {
    0: { text: '待支付', color: 'orange' },
    1: { text: '已支付', color: 'green' },
    2: { text: '已支付', color: 'green' }, // 已支付状态
    3: { text: '已取消', color: 'red' },
};

// 候补订单状态映射
const WAITLIST_STATUS = {
    0: { text: '待支付', color: 'orange' },
    1: { text: '待兑现', color: 'blue' },
    2: { text: '已兑现', color: 'green' },
    3: { text: '已取消', color: 'red' },
};

// 车次类型映射
const TRAIN_TYPES = {
    'G': { text: '高铁', color: 'green' },
    'K': { text: '快速', color: 'orange' },
};

// 席别映射
const SEAT_TYPES = {
    1: { text: '头等座', color: 'gold' },
    2: { text: '商务座', color: 'purple' },
    3: { text: '二等座', color: 'blue' },
    4: { text: '无座', color: 'red' },
};

function formatDate(datetime) {
    if (!datetime) return '';
    // 处理LocalDate或LocalDateTime格式
    if (typeof datetime === 'string') {
        return datetime.split('T')[0] || datetime.split(' ')[0] || '';
    }
    return '';
}

function formatTime(datetime) {
    if (!datetime) return '';
    
    // 处理LocalTime或LocalDateTime格式
    if (typeof datetime === 'string') {
        // 如果是纯时间格式 (HH:mm:ss)
        if (datetime.match(/^\d{2}:\d{2}:\d{2}$/)) {
            return datetime.slice(0, 5);
        }
        // 如果是日期时间格式 (YYYY-MM-DDTHH:mm:ss)
        if (datetime.includes('T')) {
            const timePart = datetime.split('T')[1];
            return timePart ? timePart.slice(0, 5) : '';
        }
        // 如果是空格分隔的日期时间格式 (YYYY-MM-DD HH:mm:ss)
        if (datetime.includes(' ')) {
            const timePart = datetime.split(' ')[1];
            return timePart ? timePart.slice(0, 5) : '';
        }
        // 如果是纯时间格式 (HH:mm)
        if (datetime.match(/^\d{2}:\d{2}$/)) {
            return datetime;
        }
    }
    
    return '';
}

function formatDateTime(datetime) {
    if (!datetime) return '';
    if (typeof datetime === 'string') {
        const datePart = datetime.split('T')[0] || datetime.split(' ')[0] || '';
        const timePart = datetime.split('T')[1] || datetime.split(' ')[1] || '';
        const time = timePart ? timePart.slice(0, 5) : '';
        return `${datePart} ${time}`;
    }
    return '';
}

export default function OrdersPage() {
    const navigate = useNavigate();
    const { user } = useAuth(); // 获取当前登录用户
    const [orders, setOrders] = useState([]);
    const [filteredOrders, setFilteredOrders] = useState([]);
    const [currentPage, setCurrentPage] = useState(1);
    const [loading, setLoading] = useState(false);
    const pageSize = 10;

    // 搜索表单状态
    const [searchForm, setSearchForm] = useState({
        orderNumber: '',
        trainNumber: '',
        orderStatus: 'all',
        startDate: null,
        endDate: null
    });

    // 使用useRef来跟踪API调用状态，防止重复调用
    const apiCallInProgress = useRef(false);

    // 获取订单数据
    const fetchOrders = useCallback(async () => {
        // 防止重复API调用
        if (apiCallInProgress.current) {
            console.log('API调用正在进行中，跳过重复调用');
            return;
        }
        
        // 检查用户是否已登录
        if (!user) {
            console.log('用户未登录，跳转到登录页');
            navigate('/login');
            return;
        }

        // 检查用户ID是否存在 - 后端返回的是userId字段
        const userId = user.userId;
        if (!userId) {
            console.log('用户ID不存在:', user);
            message.error('用户信息不完整，请重新登录');
            navigate('/login');
            return;
        }

        try {
            setLoading(true);
            apiCallInProgress.current = true;
            console.log('获取订单，用户ID:', userId);
            
            // 获取普通订单
            const orderResponse = await orderAPI.getMyOrders(userId);
            console.log('普通订单API响应:', orderResponse);
            
            // 获取候补订单
            const waitlistResult = await waitlistAPI.getMyWaitlistOrders(userId);
            console.log('候补订单API响应:', waitlistResult);
            
            let allOrders = [];
            
            if (orderResponse.status === 'SUCCESS') {
                // 转换普通订单格式，添加类型标识
                const normalOrders = (orderResponse.orders || []).map(order => ({
                    ...order,
                    orderType: 'normal',
                    isWaitlist: false
                }));
                allOrders = allOrders.concat(normalOrders);
            }
            
            if (waitlistResult.status === 'SUCCESS') {
                // 转换候补订单格式，添加类型标识
                const waitlistOrders = (waitlistResult.waitlistOrders || []).map(order => ({
                    ...order,
                    orderType: 'waitlist',
                    isWaitlist: true,
                    orderId: order.waitlistId, // 使用waitlistId作为orderId
                    orderNumber: order.orderNumber,
                    orderTime: order.orderTime,
                    totalAmount: order.totalAmount,
                    orderStatus: order.orderStatus,
                    trainId: order.trainId,
                    trainNumber: order.trainNumber,
                    departureDate: order.travelDate || order.departureDate, // 使用travelDate作为备选
                    departureTime: order.departureTime,
                    arrivalTime: order.arrivalTime,
                    departureStationName: order.departureStationName,
                    arrivalStationName: order.arrivalStationName,
                    ticketCount: order.ticketCount
                }));
                allOrders = allOrders.concat(waitlistOrders);
            }
            
            console.log('合并后的订单数据:', allOrders);
            setOrders(allOrders);
            setFilteredOrders(allOrders);
            
        } catch (error) {
            console.error('获取订单列表失败:', error);
            message.error('获取订单列表失败，请稍后重试');
            setOrders([]);
            setFilteredOrders([]);
        } finally {
            setLoading(false);
            apiCallInProgress.current = false;
        }
    }, [user]);

    useEffect(() => {
        // 只有在用户存在且已认证时才获取订单
        if (user && user.userId) {
        fetchOrders();
        }
        
        // 组件卸载时的清理函数
        return () => {
            // 清理API调用状态
            apiCallInProgress.current = false;
        };
    }, [fetchOrders]);

    // 过滤订单
    const filterOrders = useCallback(() => {
        console.log('开始过滤订单，原始订单数量:', orders.length);
        let filtered = [...orders];
        
        if (searchForm.orderNumber) {
            filtered = filtered.filter(order => 
                order.orderNumber && order.orderNumber.includes(searchForm.orderNumber)
            );
        }
        
        if (searchForm.trainNumber) {
            filtered = filtered.filter(order => 
                order.trainNumber && order.trainNumber.includes(searchForm.trainNumber)
            );
        }
        
        if (searchForm.orderStatus !== 'all') {
            filtered = filtered.filter(order => 
                order.orderStatus === parseInt(searchForm.orderStatus)
            );
        }
        
        if (searchForm.startDate && searchForm.endDate) {
            filtered = filtered.filter(order => {
                const orderDate = new Date(order.orderTime);
                return orderDate >= searchForm.startDate && orderDate <= searchForm.endDate;
            });
        }
        
        // 按订单时间倒序排列
        filtered.sort((a, b) => new Date(b.orderTime) - new Date(a.orderTime));
        
        console.log('过滤后订单数量:', filtered.length);
        setFilteredOrders(filtered);
        setCurrentPage(1);
    }, [orders, searchForm]);

    useEffect(() => {
        filterOrders();
    }, [filterOrders]);

    const handleSearch = () => {
        filterOrders();
    };

    const handleOrderClick = (order) => {
        if (order.isWaitlist) {
            // 候补订单跳转到候补订单详情页
            navigate(`/order-detail?waitlistId=${order.orderId}`);
        } else {
            // 普通订单跳转到普通订单详情页
            navigate(`/order-detail?orderId=${order.orderId}`);
        }
    };

    const handlePayOrder = (order, e) => {
        e.stopPropagation();
        navigate(`/payment?orderId=${order.orderId}`);
    };

    const handleCancelOrder = async (order, e) => {
        e.stopPropagation();
        
        // 检查用户是否已登录
        if (!user) {
            message.error('请先登录');
            navigate('/login');
            return;
        }

        // 检查用户ID是否存在 - 后端返回的是userId字段
        const userId = user.userId;
        if (!userId) {
            message.error('用户信息不完整，请重新登录');
            navigate('/login');
            return;
        }

        try {
            const response = await orderAPI.cancelOrder(order.orderId, userId);
            if (response.status === 'SUCCESS') {
                message.success('订单取消成功');
                fetchOrders(); // 重新获取订单列表
            } else {
                message.error(response.message || '取消订单失败');
            }
        } catch (error) {
            console.error('取消订单失败:', error);
            message.error('取消订单失败，请稍后重试');
        }
    };

    const handlePayWaitlistOrder = async (order, e) => {
        e.stopPropagation();
        try {
            // 跳转到支付页面
            window.location.href = `/payment?waitlistId=${order.orderId}&isWaitlist=true`;
        } catch (error) {
            console.error('跳转支付页面失败:', error);
            message.error('跳转支付页面失败');
        }
    };

    const handleCancelWaitlistOrder = async (order, e) => {
        e.stopPropagation();
        try {
            const result = await waitlistAPI.cancelWaitlistOrder(order.orderId, user.userId);
            if (result.status === 'SUCCESS') {
                message.success('候补订单取消成功');
                fetchOrders(); // 重新获取订单列表
            } else {
                message.error(result.message || '取消候补订单失败');
            }
        } catch (error) {
            console.error('取消候补订单失败:', error);
            message.error('取消候补订单失败');
        }
    };

    const cardTitle = (
        <div className="card-title">
            <FileTextOutlined style={{ marginRight: 8 }} />
            我的订单
        </div>
    );

    // 分页数据
    const startIndex = (currentPage - 1) * pageSize;
    const currentOrders = filteredOrders.slice(startIndex, startIndex + pageSize);
    
    console.log('当前页面订单数量:', currentOrders.length);
    console.log('当前订单数据:', currentOrders);

    return (
        <div className="orders-page">
            <Card
                title={cardTitle}
                className="orders-card"
                headStyle={{ padding: 0, borderRadius: '4px 4px 0 0' }}
            >
                {/* 搜索表单 */}
                <div className="search-section">
                    <div className="search-form">
                        <div className="search-row">
                            <div className="search-item">
                                <label className="search-label">订单号</label>
                                <Input
                                    placeholder="请输入订单号"
                                    value={searchForm.orderNumber}
                                    onChange={(e) => setSearchForm(prev => ({ ...prev, orderNumber: e.target.value }))}
                                    className="search-input"
                                />
                            </div>
                            <div className="search-item">
                                <label className="search-label">车次号</label>
                                <Input
                                    placeholder="请输入车次号"
                                    value={searchForm.trainNumber}
                                    onChange={(e) => setSearchForm(prev => ({ ...prev, trainNumber: e.target.value }))}
                                    className="search-input"
                                />
                            </div>
                            <div className="search-item">
                                <label className="search-label">订单状态</label>
                                <Select
                                    value={searchForm.orderStatus}
                                    onChange={(value) => setSearchForm(prev => ({ ...prev, orderStatus: value }))}
                                    className="search-select"
                                >
                                    <Option value="all">全部状态</Option>
                                    <Option value="0">待支付</Option>
                                    <Option value="1">已支付/待兑现</Option>
                                    <Option value="2">已完成/已兑现</Option>
                                    <Option value="3">已取消</Option>
                                </Select>
                            </div>
                            <div className="search-item">
                                <label className="search-label">下单时间</label>
                                <DatePicker.RangePicker
                                    value={[searchForm.startDate, searchForm.endDate]}
                                    onChange={(dates) => setSearchForm(prev => ({ 
                                        ...prev, 
                                        startDate: dates?.[0]?.toDate(), 
                                        endDate: dates?.[1]?.toDate() 
                                    }))}
                                    className="search-date"
                                    placeholder={['开始日期', '结束日期']}
                                />
                            </div>
                            <div className="search-item">
                                <Button
                                    type="primary"
                                    icon={<SearchOutlined />}
                                    onClick={handleSearch}
                                    className="search-button"
                                    loading={loading}
                                >
                                    查询
                                </Button>
                            </div>
                        </div>
                    </div>
                </div>

                <Divider />

                {/* 订单列表 */}
                <div className="orders-list">
                    {currentOrders.length > 0 ? (
                        currentOrders.map(order => (
                            <div
                                key={order.orderId}
                                className="order-item"
                                onClick={() => handleOrderClick(order)}
                                role="button"
                                tabIndex={0}
                                onKeyPress={(e) => { if (e.key === 'Enter') handleOrderClick(order); }}
                            >
                                {/* 订单头部 - 订单信息 */}
                                <div className="order-header">
                                    <div className="order-info">
                                        <span className="order-number">订单号：{order.orderNumber}</span>
                                        <span className="order-time">下单时间：{formatDateTime(order.orderTime)}</span>
                                    </div>
                                    <Tag color={order.isWaitlist ? WAITLIST_STATUS[order.orderStatus]?.color : ORDER_STATUS[order.orderStatus]?.color}>
                                        {order.isWaitlist ? WAITLIST_STATUS[order.orderStatus]?.text : ORDER_STATUS[order.orderStatus]?.text}
                                    </Tag>
                                </div>

                                {/* 订单主体内容 */}
                                <div className="order-content">
                                    {/* 左侧：车次和路线信息 */}
                                    <div className="order-left">
                                        <div className="departure-date">
                                            <span className="departure-label">发车日期</span>
                                            <span className="departure-datetime">{formatDate(order.departureDate)}</span>
                                        </div>
                                        
                                        <div className="train-info">
                                            <div className="train-header">
                                                <Tag color={TRAIN_TYPES[order.trainNumber?.[0]]?.color}>
                                                    {TRAIN_TYPES[order.trainNumber?.[0]]?.text}
                                                </Tag>
                                                <span className="train-number">{order.trainNumber}</span>
                                            </div>
                                            
                                            <div className="route-info">
                                                <div className="departure">
                                                    <div className="station-name">{order.departureStationName}</div>
                                                    <div className="departure-time">{formatTime(order.departureTime)}</div>
                                                </div>
                                                <div className="journey-line">
                                                    <div className="line"></div>
                                                    <div className="arrow">→</div>
                                                </div>
                                                <div className="arrival">
                                                    <div className="station-name">{order.arrivalStationName}</div>
                                                    <div className="arrival-time">{formatTime(order.arrivalTime)}</div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>

                                    {/* 右侧：信息卡片 */}
                                    <div className="order-right">
                                        <div className="info-card">
                                            <div className="info-item">
                                                <span className="info-label">乘车人数</span>
                                                <span className="info-value">{order.ticketCount}人</span>
                                            </div>
                                            <div className="info-item">
                                                <span className="info-label">总价</span>
                                                <span className="info-value price">¥{order.totalAmount}</span>
                                            </div>
                                            <div className="info-item">
                                                <span className="info-label">发车日期</span>
                                                <span className="info-value">{formatDate(order.departureDate)}</span>
                                            </div>
                                        </div>
                                    </div>
                                </div>

                                {/* 订单操作 */}
                                <div className="order-actions">
                                    {order.isWaitlist ? (
                                        // 候补订单操作
                                        <>
                                            {order.orderStatus === 0 && (
                                                <>
                                                    <Button 
                                                        type="primary" 
                                                        size="small"
                                                        onClick={(e) => handlePayWaitlistOrder(order, e)}
                                                    >
                                                        立即支付
                                                    </Button>
                                                    <Button 
                                                        size="small"
                                                        onClick={(e) => handleCancelWaitlistOrder(order, e)}
                                                    >
                                                        取消订单
                                                    </Button>
                                                </>
                                            )}
                                            {order.orderStatus === 1 && (
                                                <Button size="small">
                                                    等待兑现
                                                </Button>
                                            )}
                                            {order.orderStatus === 2 && (
                                                <Button size="small">
                                                    查看详情
                                                </Button>
                                            )}
                                            {order.orderStatus === 3 && (
                                                <Button size="small">
                                                    重新预订
                                                </Button>
                                            )}
                                        </>
                                    ) : (
                                        // 普通订单操作
                                        <>
                                            {order.orderStatus === 0 && (
                                                <>
                                                    <Button 
                                                        type="primary" 
                                                        size="small"
                                                        onClick={(e) => handlePayOrder(order, e)}
                                                    >
                                                        立即支付
                                                    </Button>
                                                    <Button 
                                                        size="small"
                                                        onClick={(e) => handleCancelOrder(order, e)}
                                                    >
                                                        取消订单
                                                    </Button>
                                                </>
                                            )}
                                            {order.orderStatus === 1 && (
                                                <Button size="small">
                                                    查看详情
                                                </Button>
                                            )}
                                            {order.orderStatus === 2 && (
                                                <Button size="small">
                                                    查看详情
                                                </Button>
                                            )}
                                            {order.orderStatus === 3 && (
                                                <Button size="small">
                                                    重新预订
                                                </Button>
                                            )}
                                        </>
                                    )}
                                </div>
                            </div>
                        ))
                    ) : (
                        <div className="no-orders">
                            <div className="no-orders-content">
                                <FileTextOutlined style={{ fontSize: 48, color: '#ccc', marginBottom: 16 }} />
                                <p>暂无符合条件的订单</p>
                                <p>请尝试调整搜索条件</p>
                            </div>
                        </div>
                    )}
                </div>

                {/* 分页组件 */}
                {filteredOrders.length > pageSize && (
                    <Pagination
                        current={currentPage}
                        pageSize={pageSize}
                        total={filteredOrders.length}
                        onChange={setCurrentPage}
                        showSizeChanger={false}
                        showQuickJumper
                        style={{ textAlign: 'center', marginTop: '24px' }}
                    />
                )}

                {/* 温馨提示 */}
                <div className="tips">
                    <p>温馨提示：</p>
                    <ul>
                        <li>待支付订单请在15分钟内完成支付，超时订单将自动取消</li>
                        <li>已支付订单可在发车前2小时申请退票</li>
                        <li>如需改签，请在发车前2小时办理</li>
                    </ul>
                </div>
            </Card>
        </div>
    );
}